import {freshProgress} from '../ari/vocabulary.js';
import {fresh} from '../kal/science.js';
import {newRun} from './model.js';
import {stageKey,ensureJourneys} from './journeys.js';
export function originalCourse(p,id,pack,world,stage,legacy=null){ensureJourneys(p);const key=stageKey(pack,world,stage);if(p.originalCourses[key])return p.originalCourses[key];const progress=legacy?.run?.level===stage?structuredClone(legacy):id==='ari'?freshProgress():fresh();if(!progress.run)progress.run=id==='ari'?{level:stage,checkpoint:100,done:[],collected:[],crystals:0,score:0,answers:{},bossDone:0,bossTerms:[],started:Date.now()}:{level:stage,checkpoint:100,done:[],taken:[],stars:0,score:0,crystals:[],observatory:0,answers:{},night:false};const ledger=newRun(id,pack,{...p.settings,theme:world});ledger.stage=stage;ledger.mode='paused';ledger.gameMode='original';ledger.sessionId='original-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);const collected=progress.run.crystals instanceof Array?progress.run.stars:progress.run.crystals;ledger.crystals=collected||0;ledger.bankedCrystals=ledger.crystals;return p.originalCourses[key]={progress,ledger,lastCollected:collected||0,completed:false,pending:null};}
export function captureOriginal(meta,progress){meta.progress=structuredClone(progress);const r=progress.run,n=r?(Array.isArray(r.crystals)?r.stars:r.crystals)||0:meta.lastCollected;meta.ledger.crystals+=Math.max(0,n-meta.lastCollected);meta.lastCollected=Math.max(meta.lastCollected,n);meta.ledger.score=Math.max(meta.ledger.score,r?.score||0);}
